/* Editorial overview: sourced context, proposed training, and a data decision loop. */
function thesisSection(n,title,sub){return `<header class="thesis-section-head"><span>${n}</span><div><h2>${title}</h2><p>${sub}</p></div></header>`;}
function thesisChips(items,attr,selected){return `<div class="thesis-chips" role="group">${items.map((x,i)=>`<button type="button" ${attr}="${x.id??i}" aria-pressed="${(x.id??i)===selected}">${esc(x.title??x.name)}</button>`).join('')}</div>`;}
function thesisRoute(r){return `<div class="thesis-data-route"><div><small>FILE → TENSOR</small><strong>${esc(r.input)}</strong><p>${esc(r.prepare)}</p></div><span class="thesis-arrow" aria-hidden="true">→</span><div><small>CURRENT INPUT → PREDICTION</small><strong>${esc(r.condition)}</strong></div><span class="thesis-arrow" aria-hidden="true">↔</span><div class="thesis-target"><small>OFFLINE TARGET → LOSS</small><span class="thesis-target-origin">Target từ train episode, so với prediction</span><strong>${esc(r.target)}</strong><p>${esc(r.train)}</p></div></div><p class="thesis-runtime-note"><strong>Inference:</strong> ${esc(r.runtime)}</p>`;}
function modelAIModeMarkup(x){return `<p class="model-ai-caption">${esc(x.caption)}</p>${x.id==='video'?`<div class="model-ai-branch-note"><span><strong>Current:</strong> VLM + conditioning → projection</span><span><strong>Future target:</strong> frozen encoder → embedding</span><b>Hai nhánh → implicit alignment loss</b></div>`:''}<div class="model-ai-nodes" data-model-flow="${esc(x.id)}">${x.nodes.map((n,i)=>`<article><div class="model-ai-node-top"><b>0${i+1}</b><small>${esc(n.tag)}</small></div><h3>${esc(n.name)}</h3><p>${esc(n.body)}</p><div class="model-ai-node-output"><small>OUTPUT</small><strong>${esc(n.output)}</strong></div><span class="model-ai-scope">${esc(n.scope)}</span></article>`).join('')}</div><div class="model-ai-target"><span>${x.id==='run'?'RUNTIME':'OFFLINE TARGETS'}</span><p>${esc(x.target)}</p></div><div class="model-ai-recipe"><div><small>${x.id==='run'?'WEIGHTS':'LOSS → GRADIENT'}</small><strong>${esc(x.loss)}</strong><p>${esc(x.modules)}</p></div><div><small>ĐẦU RA BÀN GIAO</small><strong>${esc(x.deliver)}</strong><p>${esc(x.contrast)}</p></div></div>`;}
function renderModelAI(){const m=OVERVIEW_FLYWHEEL.model;return `<section id="model-ai-panel" class="model-ai-panel"><header class="model-ai-heading"><div><span class="thesis-kicker">MODEL AI · POLICY NỀN + CÁC NHÁNH HỌC</span><h2>${esc(m.name)}</h2><p>${esc(m.purpose)}</p></div><span class="model-ai-status">${esc(m.status)}</span></header><div class="model-ai-selection"><span><strong>Kế thừa</strong> Eagle VLM + DiT action policy</span><span><strong>Đội xây</strong> Adapters / supervision routes / train–eval receipts</span></div>${thesisChips(m.modes,'data-model-ai-mode','run')}<div id="model-ai-view" aria-live="polite">${modelAIModeMarkup(m.modes[0])}</div><details class="thesis-details"><summary>World Model nằm ở đâu trong solution?</summary><div class="model-ai-world">${m.worldRoles.map(r=>`<article><h3>${esc(r.name)}</h3><p>${esc(r.role)}</p><small>${esc(r.status)}</small></article>`).join('')}</div><p class="thesis-note"><a href="#research">So recipes của 7 model →</a></p></details><a class="model-ai-source" href="${esc(m.source)}" target="_blank" rel="noopener">Architecture / flow matching / FLARE của GR00T N1.5 · nguồn NVIDIA ↗</a></section>`;}
function initModelAI(signal){const root=document.querySelector('#model-ai-panel');if(!root)return;root.addEventListener('click',e=>{const b=e.target.closest('[data-model-ai-mode]');if(!b||!root.contains(b))return;const mode=OVERVIEW_FLYWHEEL.model.modes.find(x=>x.id===b.dataset.modelAiMode);root.querySelector('#model-ai-view').innerHTML=modelAIModeMarkup(mode);root.querySelectorAll('[data-model-ai-mode]').forEach(el=>el.setAttribute('aria-pressed',String(el===b)));},{signal});}
function overviewCaseMarkup(index){const x=OVERVIEW_FLYWHEEL.pitch.caseSteps[index];return `<small>BƯỚC ${index+1} · ${esc(x.artifact)}</small><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p>`;}
function renderFlywheelOverview(){const d=OVERVIEW_FLYWHEEL,p=d.pitch,c=d.cost;
 const budget=calculateThesisBudget({roots:c.roots,yield:c.yield,operatorRate:c.operatorRate,engineerRate:c.engineerRate,engineeringHours:c.engineeringHours,gpuHours:Object.values(c.gpuHours).reduce((a,b)=>a+b,0)});
 const total=budget.total.toLocaleString('vi-VN',{minimumFractionDigits:2,maximumFractionDigits:2});
 return `<div class="thesis-page overview-pitch">
 <section class="thesis-hero">
  <div class="thesis-hero-copy"><span class="thesis-kicker">Ý TƯỞNG & VẤN ĐỀ</span><h1>Robot làm sai.<br>Thu thêm gì để <em>học đúng?</em></h1><p><strong>${esc(p.case)}</strong> ${esc(p.problem)}</p><div class="thesis-hero-tags"><span>Đúng tín hiệu</span><span>Đúng điều kiện</span><span>Đáng công sử dụng</span></div></div>
  <figure class="overview-task"><svg viewBox="0 0 340 240" role="img" aria-label="Minh họa: vị trí linh kiện thay đổi, robot cần gắp và đặt vào ô A1"><defs><marker id="overview-arrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto"><path d="M0 0L10 5L0 10Z" fill="#116b70"/></marker></defs><rect x="10" y="20" width="320" height="195" rx="18" fill="#fff" stroke="#cadcde"/><path d="M35 70H305M35 120H305M35 170H305M85 40V195M145 40V195M205 40V195M265 40V195" stroke="#edf3f3"/><rect x="241" y="132" width="58" height="55" rx="9" fill="#e6f1ed" stroke="#116b70"/><text x="270" y="166" text-anchor="middle" fill="#116b70" font-size="20" font-weight="700">A1</text><rect x="83" y="133" width="25" height="25" rx="4" fill="none" stroke="#a3b6bd" stroke-dasharray="4 3"/><rect x="137" y="92" width="28" height="28" rx="4" fill="#dba654"/><path d="M105 139Q114 112 134 110" fill="none" stroke="#b78335" stroke-width="2" stroke-dasharray="4 3"/><path d="M157 124Q185 175 230 161" fill="none" stroke="#116b70" stroke-width="2" marker-end="url(#overview-arrow)"/><path d="M40 40L90 72L95 110M78 111V123M111 111V123M78 111H111" fill="none" stroke="#173a49" stroke-width="8" stroke-linecap="round"/><text x="194" y="60" fill="#607680" font-size="13">Vị trí thay đổi</text><text x="27" y="235" fill="#607680" font-size="12">Task GR1 sim đề xuất · Minh họa</text></svg></figure>
 </section>
 <div class="overview-effort" aria-label="Công việc phát sinh"><span>Thu / sửa mẫu</span><b>→</b><span>Reset + QA</span><b>→</b><span>Train + thử lại</span><strong>Giờ công + giờ máy</strong></div>
 <p class="thesis-scope">${esc(p.scope)}</p>
 ${monthProofView()}
 <section class="thesis-section" id="overview-evidence">${thesisSection('01','Vì sao cần giải bài toán dữ liệu?','Dẫn chứng bên ngoài cho cơ hội nghiên cứu; chưa phải hiệu quả của dự án.')}
 <div class="thesis-evidence">${d.evidence.map(e=>`<article><span>${esc(e.label)}</span><strong>${esc(e.metric)}</strong><p>${esc(e.context)}</p><a href="${esc(e.url)}" target="_blank" rel="noopener">${esc(e.source)} ↗</a></article>`).join('')}</div>
 <p class="overview-source-note"><a href="${esc(d.video.url)}" target="_blank" rel="noopener">Video nguồn đã đối chiếu transcript ↗</a> · Dẫn chứng Index / Helix; chưa kiểm trực quan toàn bộ video.</p>
 </section>
 <section class="thesis-section" id="overview-solution">${thesisSection('02','Data Core × Model Engine Core','Chọn dữ liệu hữu ích → học thành hành động → lấy kết quả để quyết định vòng sau.')}
 <div class="overview-cores"><article><small>DATA CORE</small><h3>Dữ liệu dùng được</h3><p>Chọn → QA → phiên bản / nguồn gốc.</p><strong>Đầu ra: batch + targets + masks</strong><a href="#architecture">Kiến trúc dữ liệu →</a></article><article><small>MODEL ENGINE CORE</small><h3>Policy học và thực thi</h3><p>GR00T N1.5 qua FluxVLA: train → eval → inference.</p><strong>Đầu ra: checkpoint + action chunk</strong><a href="#engine">Model, recipe & robot runtime →</a></article></div>
 <div class="overview-model-strip" aria-label="Model AI khi inference"><span>RGB + lệnh</span><b>→</b><span>VLM: features</span><b>→</b><span>Action Expert <small>+ robot state</small></span><b>→</b><span>Action chunk <small>→ controller → robot</small></span></div>
 <p class="overview-source-note">Kế thừa pretrained VLA. Đội xây phần dữ liệu, tích hợp và kiểm chứng; chưa native A1 training. Features là biểu diễn, không phải nguồn dataset mới.</p>
 <div class="overview-loop" id="overview-flywheel"><header><span class="thesis-kicker">DATA FLYWHEEL · TÌNH HUỐNG GẮP HỤT</span><h3>Mỗi vòng phải trả lời: bổ sung gì, học phần nào, có ích không?</h3></header>
 <div class="overview-loop-steps" role="group" aria-label="Sáu bước data flywheel">${p.caseSteps.map((x,i)=>`<button type="button" data-overview-step="${i}" aria-pressed="${i===0}" aria-controls="overview-loop-detail"><span>0${i+1}</span><strong>${esc(x.title)}</strong></button>`).join('')}</div>
 <article id="overview-loop-detail" aria-live="polite">${overviewCaseMarkup(0)}</article>
 <div class="overview-loop-return"><span aria-hidden="true">↶</span> Kết quả + tổng công → chọn dữ liệu cho vòng tiếp theo</div>
 </div>
 <p class="overview-hypothesis"><strong>Giả thuyết cần chứng minh:</strong> đạt cùng chất lượng với ít mẫu robot gốc hoặc tổng công thấp hơn đối chứng. Kiến trúc model và controller vẫn có thể là điểm nghẽn.</p>
 </section>
 <section class="thesis-section" id="overview-training">${thesisSection('03','Bắt đầu bằng robot data. Mở rộng có kiểm định.','PoC dùng public task đúng nhãn trước. A1 bên dưới là proxy nghiên cứu mở rộng.')}
 <div class="overview-data-lineage"><article><small>PROXY A1 MỞ RỘNG · R_A1 · DỰ KIẾN THU</small><h3>Expert / correction robot đích</h3><p>GR1 sim: MP4 + Parquet + instruction + calibration.</p><strong>Tín hiệu: RGB / text / state / action</strong></article><div class="overview-derived-arrow" aria-label="Từ mẫu gốc tạo biến thể">Tạo biến thể<span>→</span></div><article><small>CÁCH TẠO · S_exec · CHƯA SINH</small><h3>Đổi điều kiện → execute → QA</h3><p>Ghi lại ảnh, state và action sau thực thi simulator.</p><strong>Cùng schema robot + nguồn gốc mẫu</strong></article></div>
 <p class="overview-source-note"><strong>Synthetic là cách tạo dữ liệu.</strong> Augmentation chỉ giữ nhãn khi hợp lệ; sim execution tạo trajectory và nhãn mới. Generated video có thể thiếu action.</p>
 <div class="overview-training-path">${[['0','Kiểm tương thích','Checkpoint + public GR1 sample'],['1','Học baseline R','Mẫu robot đích → action loss'],['2','Học candidate R+S','Biến thể QA + replay → update'],['3','Eval → inference','Reload → rollout → chấm task']].map(([n,t,b])=>`<article><span>${n}</span><h3>${t}</h3><p>${b}</p></article>`).join('')}</div>
 <p class="overview-source-note">Train: VLM mã hóa ảnh/text; Action Expert học future action targets. Chỉ cập nhật modules theo recipe đã chốt. Inference dùng quan sát hiện tại và history theo config, không đọc future ground truth.</p>
 <details class="thesis-details"><summary>Human video, action-free và World Models nằm ở đâu?</summary><p>Human motion và FOCA-style video là pilots riêng, có kiểm quyền dùng, geometry / targets và đối chứng trước khi tích hợp. Human wrists chưa là robot joint actions; video thiếu action không dùng robot-action loss. World Models có thể hỗ trợ tạo dữ liệu hoặc representation theo recipe; chưa là module bắt buộc của MVP.</p><a href="#sources">Dataset & file formats →</a> · <a href="#research">Khảo sát VLA / World Models →</a></details>
 <div class="thesis-inline-links"><a href="#learning">Xem file → tensor → loss → weights →</a><a href="#examples">Public data & reference đã chạy →</a></div>
 </section>
 <section class="thesis-section" id="overview-cost">${thesisSection('04','Chi phí hiện trạng ≠ ngân sách thử nghiệm','Tính cả thu / reset / QA / generation / train / eval / retry; chưa quy thành savings.')}
 <div class="overview-cost-pair"><article><small>HIỆN TRẠNG · CẦN KHẢO SÁT</small><h3>Một lần đổi thao tác tốn bao nhiêu?</h3><p>Cần log giờ operator, reset, QA, kỹ sư và giờ máy của cùng task.</p><strong>Chưa có baseline DENSO để định lượng.</strong></article><article class="overview-budget"><small>PILOT SIM · GIẢ ĐỊNH MINH HỌA</small><strong class="overview-budget-total">${total} USD</strong><p>240 giờ kỹ sư + thu / QA + 180 GPU-giờ + lưu trữ.</p><span>Chưa gồm robot/cell, CPU riêng, license, thuế và downtime; chưa tổng triển khai hay khoản tiết kiệm.</span><a href="#business">Bảng tính & các giả định →</a></article></div>
 </section>
 <section class="thesis-section overview-proof" id="overview-validation">${thesisSection('05','Chứng minh bằng task, dữ liệu và tổng công','So R với R+S cùng recipe và phạm vi cập nhật; kiểm giá trị chọn dữ liệu bằng đối chứng riêng.')}
 <div class="overview-measures"><article><h3>Robot làm tốt hơn?</h3><p>Hoàn thành toàn task, điều kiện mới và regression; không chỉ loss giảm.</p></article><article><h3>Dữ liệu có ích hơn?</h3><p>Đếm mẫu gốc và coverage; biến thể không thành demonstrations độc lập.</p></article><article><h3>Tổng công có giảm?</h3><p>So tại cùng yêu cầu chất lượng; tính cả vòng không có gain.</p></article></div>
 <p class="overview-source-note">Reference MuJoCo nhỏ đã chạy, chưa VLM/GR1. Native A1, human transfer và savings chưa đo. Chọn trên development; final độc lập ngoài vòng tune.</p>
 <div class="overview-next"><div><strong>Đầu ra dự kiến</strong><span>Dataset release · policy / skill bundle · trace / scorer · báo cáo chất lượng–chi phí.</span></div><div><strong>PoC 30 ngày, hardware có gate</strong><span>Public data trước, hướng tới robot thật trước 16/11; robot do BTC bố trí. Human/video là mở rộng.</span></div></div>
 <div class="thesis-inline-links"><a class="button" href="#validation">Thiết kế kiểm chứng →</a><a href="#outcomes">Đầu ra & tiêu chí →</a><a href="#roadmap">Lộ trình →</a><a href="data/denso-form-draft.md" download>Tải nội dung form ↓</a></div>
 </section>
 </div>`;
}
function calculateThesisBudget(x){const c=OVERVIEW_FLYWHEEL.cost,attempts=Math.ceil(x.roots/x.yield),captureHours=attempts*c.minutesPerAttempt/60,qaHours=attempts*c.qaMinutesPerAttempt/60;const lines=[['Thu / reset',captureHours*x.operatorRate,`${attempts} attempts · ${captureHours.toFixed(1)} giờ`],['QA attempts',qaHours*x.engineerRate,`${qaHours.toFixed(1)} engineer-giờ`],['Tích hợp / xử lý / báo cáo',x.engineeringHours*x.engineerRate,`${x.engineeringHours} engineer-giờ`],['GPU cap',x.gpuHours*c.a100Rate,`${x.gpuHours} A100 GPU-giờ`],['Storage',c.storageGB*c.storageMonths*c.storageRate,`${c.storageGB} GB × ${c.storageMonths} tháng`]];return {attempts,lines,total:lines.reduce((s,l)=>s+l[1],0)};}
function renderExampleNarrative(){const publicExamples=examples();return head('DATA → MODEL → EVAL → ROBOT','Theo một episode.<br>Hiểu từng biến đổi.','GR1 public sample cho thấy dữ liệu thật; native training là thiết kế. Reference MuJoCo nhỏ có receipts riêng để xem model học và thực thi, chưa dùng GR1 public data.')+`<div id="example-training-guide" class="thesis-example-guide">
 <div class="thesis-training-steps">${[['01','Files & signals','Đọc video, state và action target'],['02','Training model','Processor → features → target/loss'],['03','Benchmark','Native chưa đo; reference có receipts'],['04–05','Inference & flywheel','Prediction → command → response → kiểm / update']].map(([n,t,b])=>`<article><span>${n}</span><h3>${t}</h3><p>${b}</p></article>`).join('')}</div>
 ${thesisSection('01','Data: video đi cùng tín hiệu nào?','Public GR1 data thuộc tác giả; row action là dataset target, chưa issued command của đội.')}${gr1Example()}
 <section class="thesis-section">${thesisSection('02','Từ files đến training tensors và model','Đường native dự kiến; chưa feature vector hoặc gradient receipt từ GR1 của project.')}${thesisRoute(OVERVIEW_FLYWHEEL.routes[0])}<p class="thesis-note">RGB 256×256 và state/action29D là metadata sample trên đĩa. Processor resolution, token/feature dimensions và action horizon lấy selected config; không suy từ kích thước file. Robot profile mới phải pin lại.</p><div class="thesis-inline-links"><a href="#learning">Khám phá robot / video / motion routes →</a><a href="#sources">Manifest và formats →</a></div></section>
 <section class="thesis-section">${thesisSection('03','Benchmark: đọc cả phạm vi và kết quả','Project native A1: chưa đo. Reference thu nhỏ: model4D/state idealized, sequencer scripted và weld grasp; không VLM/GR1.')}
 <div id="example-benchmark" class="thesis-benchmark" aria-live="polite"><p>Đang đọc report reference…</p></div><p class="thesis-note">Reference không huấn luyện bằng episode GR1 phía trên. Local gain/training loss phải đi cùng final/regression. Chi phí tiền và human transfer chưa có evidence từ reference.</p><a href="#validation">Kế hoạch đo A1 và final độc lập →</a></section>
 <section class="thesis-section">${thesisSection('04','Inference: model dự đoán, controller thực thi','Đọc playback theo measured positions và action/command/readback đã ghi, không animation tự quyết định kết quả.')}${engineeringExampleMarkup()}</section>
 <section class="thesis-section">${thesisSection('05','Có lỗi: kiểm gì, lấy data gì, train phần nào?','Các cases dưới đây là kế hoạch native; dùng controlled tests trước khi chọn scope update.')}${thesisChips(OVERVIEW_FLYWHEEL.errors,'data-example-error','contact')}<div id="example-error" class="thesis-error" aria-live="polite"></div><div class="thesis-solution-band"><strong>Vòng sau</strong><span>Evidence → acquisition plan → QA release → update + replay → full-task / cost → quyết định</span></div><a class="button" href="#architecture">Mở data flywheel →</a></section>
 <details class="thesis-details"><summary>Thêm video G1, HumanEgo, simulation và generated video từ tác giả</summary><p class="thesis-note">Các tasks/embodiments riêng; không ghép media thành paired pipeline A1 hoặc training result của đội.</p>${publicExamples.slice(publicExamples.indexOf('<section class="panel">'))}</details></div>`;}
async function initExampleNarrative(signal){const root=document.querySelector('#example-training-guide');if(!root)return;const show=id=>{const x=OVERVIEW_FLYWHEEL.errors.find(x=>x.id===id);root.querySelector('#example-error').innerHTML=`<div><small>QUAN SÁT</small><h3>${esc(x.title)}</h3><p>${esc(x.observe)}</p></div><div class="thesis-error-actions">${[['Kiểm trước',x.test],['Chọn dữ liệu',x.collect],['Train phần nào?',x.update],['Đo lại',x.eval]].map(([t,b],i)=>`<div><span>${i+1}</span><p><strong>${t}</strong>${esc(b)}</p></div>`).join('')}</div>`;root.querySelectorAll('[data-example-error]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.exampleError===id)));};show('contact');root.addEventListener('click',e=>{const b=e.target.closest('[data-example-error]');if(b)show(b.dataset.exampleError);},{signal});try{const res=await fetch('data/engineering/report.json',{signal});if(!res.ok)throw Error('report');const r=await res.json();if(signal.aborted)return;root.querySelector('#example-benchmark').innerHTML=table(['Reference run','Independent seed roots','Training MSE','Final whole-task','Scope'],['R','S','C'].map(k=>[k,r.training[k].independent_roots,Number(r.training[k].loss).toExponential(2),`${r.final[k].successes}/${r.final[k].trials}`,k==='S'?'Sim variants · reference only':k==='C'?'Correction · chưa đạt final':'Baseline · reference only']))+`<p class="thesis-note"><a href="data/engineering/report.json" target="_blank" rel="noopener">Report thực + conditions ↗</a> · S variants vẫn descendants của training root, không independent demonstrations. Native A1: chưa training/eval.</p>`;}catch(e){if(!signal.aborted)root.querySelector('#example-benchmark').textContent='Chưa đọc được local report. Mở reference report từ phần playback.';}}
function initFlywheelOverview(signal){const root=document.querySelector('.overview-pitch');if(!root)return;
 root.addEventListener('click',e=>{const button=e.target.closest('[data-overview-step]');if(!button||!root.contains(button))return;
 const index=Number(button.dataset.overviewStep);if(!OVERVIEW_FLYWHEEL.pitch.caseSteps[index])return;
 root.querySelector('#overview-loop-detail').innerHTML=overviewCaseMarkup(index);
 root.querySelectorAll('[data-overview-step]').forEach(b=>b.setAttribute('aria-pressed',String(b===button)));
 },{signal});
}
